"""Rank feasible schedules by user preferences."""

from dataclasses import dataclass, field

from planner.model import PlannerError, Section
from planner.solver import Choice

DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
DAY_ORDER = {day: index for index, day in enumerate(DAYS)}

# Metrics are compared lexicographically in this order, so the first one is the
# most important preference.
METRICS = ("days", "early", "gaps", "span")


@dataclass(frozen=True)
class Preferences:
    """Ordered preferences used to rank schedules.

    ``days``        fewest days with any class on campus
    ``early``       fewest meetings starting before ``not_before``
    ``gaps``        smallest total waiting time between classes on a day
    ``span``        smallest total time from the first to the last class per day
    """

    order: tuple[str, ...] = METRICS
    not_before: int = 9 * 60
    max_results: int = 10


@dataclass(frozen=True)
class Metrics:
    """Measured values of a schedule; lower is better for every field."""

    days: int
    early: int
    gaps: int
    span: int

    def as_dict(self) -> dict[str, int]:
        return {"days": self.days, "early": self.early, "gaps": self.gaps, "span": self.span}

    def as_tuple(self, order: tuple[str, ...]) -> tuple[int, ...]:
        values = self.as_dict()
        return tuple(values[name] for name in order)


@dataclass
class RankedSchedule:
    """A feasible schedule together with its measured and weighted scores."""

    choices: list[Choice]
    metrics: Metrics
    score: int = 0
    rank: int = 0

    @property
    def meetings(self) -> list[Section]:
        return [row for choice in self.choices for row in choice.meetings]


@dataclass
class Ranking:
    """Result of :func:`rank_schedules`."""

    top: list[RankedSchedule]
    total: int
    truncated: bool = False
    seen: int = field(default=0)


def normalise_order(names: list[str] | tuple[str, ...] | None) -> tuple[str, ...]:
    """Validate a preference order, filling in the remaining metrics."""
    if names is None:
        return METRICS
    cleaned: list[str] = []
    for name in names:
        key = name.strip().lower()
        if key not in METRICS:
            raise PlannerError(
                f"unknown preference {name!r}; choose from {', '.join(METRICS)}"
            )
        if key not in cleaned:
            cleaned.append(key)
    if not cleaned:
        raise PlannerError("at least one preference is required")
    return tuple(cleaned) + tuple(name for name in METRICS if name not in cleaned)


def measure(meetings: list[Section], *, not_before: int = 9 * 60) -> Metrics:
    """Compute the preference metrics of a set of meetings.

    A meeting counts as early when it starts before ``not_before`` (minutes
    after midnight). Gaps are the idle minutes between consecutive classes on
    the same day; ``span`` is the first-to-last distance per day.
    """
    per_day: dict[str, list[Section]] = {}
    for row in meetings:
        per_day.setdefault(row.day, []).append(row)
    gaps = 0
    span = 0
    for rows in per_day.values():
        rows = sorted(rows, key=lambda r: (r.start, r.end))
        cursor = rows[0].end
        for row in rows[1:]:
            if row.start > cursor:
                gaps += row.start - cursor
            cursor = max(cursor, row.end)
        span += rows[-1].end - rows[0].start
    early = sum(1 for row in meetings if row.start < not_before)
    return Metrics(days=len(per_day), early=early, gaps=gaps, span=span)


def weighted(metrics: Metrics, order: tuple[str, ...]) -> int:
    """Combine metrics into one number, weighting earlier preferences more.

    The first preference counts ``len(order)`` times, the next one less, so a
    single-unit improvement of a higher preference always beats any change in
    the preferences below it (each lower metric is bounded by the number of
    meetings times a day's minutes, far below the weight ratio).
    """
    weights = list(range(len(order), 0, -1))
    values = metrics.as_dict()
    return sum(weights[i] * values[name] for i, name in enumerate(order))


def sort_key(schedule: RankedSchedule, order: tuple[str, ...]) -> tuple:
    """Stable ordering: preferences in order, then a deterministic tie-break."""
    return (
        schedule.metrics.as_tuple(order),
        [(c.course, c.section) for c in schedule.choices],
    )


def rank(
    schedules: list[list[Choice]],
    *,
    preferences: Preferences | None = None,
    total: int | None = None,
) -> Ranking:
    """Rank and return the best schedules, best first.

    Ranks are 1-based and ties are kept (equal metrics share the rank shown
    by the earlier schedule's position), up to ``preferences.max_results``.
    """
    prefs = preferences or Preferences()
    order = normalise_order(prefs.order)
    if prefs.max_results < 1:
        raise PlannerError("max_results must be at least 1")
    ranked = [
        RankedSchedule(choices, measure(
            [row for choice in choices for row in choice.meetings],
            not_before=prefs.not_before,
        ))
        for choices in schedules
    ]
    for item in ranked:
        item.score = weighted(item.metrics, order)
    ranked.sort(key=lambda item: sort_key(item, order))
    seen_order: list[tuple[int, ...]] = []
    for item in ranked:
        key = item.metrics.as_tuple(order)
        if key not in seen_order:
            seen_order.append(key)
        item.rank = seen_order.index(key) + 1
    top = ranked[: prefs.max_results]
    return Ranking(
        top=top,
        total=total if total is not None else len(schedules),
        truncated=len(schedules) < (total if total is not None else len(schedules)),
        seen=len(schedules),
    )

"""Search for the best schedules without enumerating every feasible one."""

from dataclasses import dataclass

from planner.model import PlannerError
from planner.preferences import (
    RankedSchedule,
    measure,
    normalise_order,
    sort_key,
    weighted,
)
from planner.solver import (
    Choice,
    _explain_impossible,
    _no_overlap,
    _self_clash,
    describe,
    group_sections,
)

DEFAULT_PATIENCE = 20_000


@dataclass
class SearchResult:
    """Best schedules found, best first, plus what the search did."""

    best: list[RankedSchedule]
    total: int
    complete: bool
    explored: int


def _option_metrics(choice: Choice, not_before: int) -> dict[str, int]:
    return measure(choice.meetings, not_before=not_before).as_dict()


def search(
    sections,
    courses: list[str],
    *,
    order: tuple[str, ...] | None = None,
    not_before: int = 9 * 60,
    limit: int = 10,
    patience: int = DEFAULT_PATIENCE,
) -> SearchResult:
    """Find up to ``limit`` best schedules according to ``order``.

    The search is a depth-first branch and bound: each partial schedule gets an
    admissible lower bound for every metric (per-day values can only grow as
    real numbers grow, and an unplaced course contributes its cheapest option),
    as well as an optimistic tie-break key. A branch is dropped as soon as its
    key cannot beat the worst schedule already stored in the top ``limit``.

    Counting stops after ``patience`` explored complete or partial nodes once
    ``limit`` schedules are known, so a huge or heavily overlapping request
    still answers quickly; ``complete`` reports whether the count is exact.
    """
    order = normalise_order(order)
    if limit < 1:
        raise PlannerError("max_results must be at least 1")
    if not courses:
        raise PlannerError("no courses requested")
    grouped = group_sections(sections)
    duplicate = {name for name in courses if courses.count(name) > 1}
    if duplicate:
        raise PlannerError("course requested more than once: " + ", ".join(sorted(duplicate)))
    unknown = [name for name in courses if name not in grouped]
    if unknown:
        known = ", ".join(grouped) or "(none)"
        raise PlannerError(
            f"unknown course(s): {', '.join(unknown)} (known courses: {known})"
        )

    options: list[list[Choice]] = [
        [Choice(g.course, g.section, list(g.meetings)) for g in grouped[name]]
        for name in courses
    ]
    for name, choices in zip(courses, options):
        for choice in choices:
            if _self_clash(choice.meetings):
                raise PlannerError(
                    f"course {name} is unusable: section {choice.section} already"
                    f" has overlapping meetings ({describe(choice)})"
                )

    # Per-option metrics and per-course cheapest option for the lower bound.
    option_values = [
        [_option_metrics(choice, not_before) for choice in choices] for choices in options
    ]
    lowest: list[dict[str, int]] = []
    for values in option_values:
        lowest.append({k: min(v[k] for v in values) for k in values[0]})

    state = {
        "explored": 0,
        "truncated": False,
        "found": 0,
        "complete_found": 0,
        "best": [],  # list of RankedSchedule, worst first
        "dead_end_examples": [],
    }

    def lower_bound(position: int, chosen: list[Choice]) -> tuple:
        remaining = range(position, len(options))
        metrics = {
            key: sum(lowest[i][key] for i in remaining)
            for key in lowest[0]
        }
        if chosen:
            combined = measure(
                [row for choice in chosen for row in choice.meetings],
                not_before=not_before,
            ).as_dict()
            for key in metrics:
                metrics[key] += combined[key]
        placeholders = [
            Choice(course, "?") for course in courses[position:]
        ]
        key = [(c.course, c.section) for c in chosen] + [
            (p.course, "") for p in placeholders
        ]
        return (tuple(metrics[name] for name in order), key)

    def worst_key() -> tuple | None:
        if len(state["best"]) < limit:
            return None
        return state["worst_key"]

    def offer(choices: list[Choice]) -> None:
        metrics = measure(
            [row for choice in choices for row in choice.meetings],
            not_before=not_before,
        )
        item = RankedSchedule(list(choices), metrics)
        item.score = weighted(metrics, order)
        key = sort_key(item, order)
        best = state["best"]
        worst = worst_key()
        if worst is not None and key >= worst:
            return
        insert_at = 0
        while insert_at < len(best) and sort_key(best[insert_at], order) <= key:
            insert_at += 1
        best.insert(insert_at, item)
        if len(best) > limit:
            best.pop()
        state["worst_key"] = sort_key(best[-1], order) if len(best) >= limit else None

    def visit(position: int, chosen: list[Choice]) -> None:
        state["explored"] += 1
        worst = worst_key()
        if worst is not None and state["found"] >= limit:
            bound = lower_bound(position, chosen)
            if bound >= worst:
                return
            if state["truncated"] or state["explored"] > patience:
                state["truncated"] = True
                return
        if position == len(options):
            state["found"] += 1
            offer(chosen)
            return
        for candidate in options[position]:
            if all(_no_overlap(candidate, other) for other in chosen):
                chosen.append(candidate)
                visit(position + 1, chosen)
                chosen.pop()
            elif not chosen:
                continue

    visit(0, [])
    if state["found"] == 0:
        raise PlannerError(_explain_impossible(courses, options))
    best = state["best"]
    seen_order: list[tuple] = []
    for item in best:
        key = item.metrics.as_tuple(order)
        if key not in seen_order:
            seen_order.append(key)
        item.rank = seen_order.index(key) + 1
    complete = not state["truncated"]
    return SearchResult(
        best=best,
        total=state["found"],
        complete=complete,
        explored=state["explored"],
    )

"""Search for the best schedules without enumerating every feasible one."""

from dataclasses import dataclass

from planner.model import PlannerError, Section
from planner.preferences import (
    METRICS,
    RankedSchedule,
    measure,
    normalise_order,
    sort_key,
    weighted,
)
from planner.solver import (
    Choice,
    _explain_impossible,
    _no_overlap,
    _self_clash,
    describe,
    group_sections,
)

DEFAULT_PATIENCE = 20_000


@dataclass
class SearchResult:
    """Best schedules found (best first) plus what the search did.

    ``total`` is the number of feasible schedules found; ``complete`` says
    whether that count is exact (False when the search hit its budget or was
    cut short by an optimistic bound once the top ``limit`` were known).
    """

    best: list[RankedSchedule]
    total: int
    complete: bool
    explored: int


def _key(metrics: dict[str, int], order: tuple[str, ...], prefix: list[tuple[str, str]]) -> tuple:
    return (tuple(metrics[name] for name in order), prefix)


def search(
    sections: list[Section],
    courses: list[str],
    *,
    order: list[str] | tuple[str, ...] | None = None,
    not_before: int = 9 * 60,
    limit: int = 10,
    patience: int = DEFAULT_PATIENCE,
) -> SearchResult:
    """Find up to ``limit`` best feasible schedules according to ``order``.

    Depth-first branch and bound. Every partial schedule gets an admissible
    lower bound on each metric: per-day metrics can only grow when more
    meetings are added, and each unplaced course contributes at worst its
    cheapest option. Branches whose optimistic key cannot beat the worst
    schedule already stored are dropped, so a request whose first feasible
    schedule is found early never enumerates the whole search space.

    ``patience`` caps the nodes visited after the top ``limit`` is known, so
    degenerate requests (thousands of equally good schedules) still answer
    quickly; the counts are then reported as approximate via ``complete``.
    """
    order = normalise_order(order)
    if limit < 1:
        raise PlannerError("max_results must be at least 1")
    if not courses:
        raise PlannerError("no courses requested")
    grouped = group_sections(sections)
    duplicate = {name for name in courses if courses.count(name) > 1}
    if duplicate:
        raise PlannerError("course requested more than once: " + ", ".join(sorted(duplicate)))
    unknown = [name for name in courses if name not in grouped]
    if unknown:
        known = ", ".join(grouped) or "(none)"
        raise PlannerError(
            f"unknown course(s): {', '.join(unknown)} (known courses: {known})"
        )

    options: list[list[Choice]] = [
        [Choice(g.course, g.section, list(g.meetings)) for g in grouped[name]]
        for name in courses
    ]
    for name, choices in zip(courses, options):
        for choice in choices:
            if _self_clash(choice.meetings):
                raise PlannerError(
                    f"course {name} is unusable: section {choice.section} already"
                    f" has overlapping meetings ({describe(choice)})"
                )

    option_values = [
        [measure(choice.meetings, not_before=not_before).as_dict() for choice in choices]
        for choices in options
    ]
    lowest = [{name: min(v[name] for v in values) for name in METRICS} for values in option_values]

    def lower_bound(position: int, chosen: list[Choice]) -> tuple:
        remaining = list(range(position, len(options)))
        totals = {
            name: sum(lowest[i][name] for i in remaining) for name in METRICS
        }
        if chosen:
            partial = measure(
                [row for choice in chosen for row in choice.meetings],
                not_before=not_before,
            ).as_dict()
            for name in totals:
                totals[name] += partial[name]
        prefix = [(c.course, c.section) for c in chosen]
        prefix += [(courses[i], "") for i in remaining]
        return _key(totals, order, prefix)

    best: list[RankedSchedule] = []
    worst_key: tuple | None = None
    stats = {"found": 0, "explored": 0, "capped": False}

    def offer(chosen: list[Choice]) -> None:
        nonlocal worst_key
        metrics = measure(
            [row for choice in chosen for row in choice.meetings],
            not_before=not_before,
        )
        item = RankedSchedule(list(chosen), metrics)
        item.score = weighted(metrics, order)
        key = sort_key(item, order)
        if worst_key is not None and key >= worst_key:
            return
        insert_at = 0
        while insert_at < len(best) and sort_key(best[insert_at], order) <= key:
            insert_at += 1
        best.insert(insert_at, item)
        if len(best) > limit:
            best.pop()
        worst_key = sort_key(best[-1], order) if len(best) >= limit else None

    def visit(position: int, chosen: list[Choice]) -> None:
        stats["explored"] += 1
        if worst_key is not None:
            if lower_bound(position, chosen) >= worst_key:
                return
            if stats["explored"] > patience:
                stats["capped"] = True
                return
        if position == len(options):
            stats["found"] += 1
            offer(chosen)
            return
        for candidate in options[position]:
            if all(_no_overlap(candidate, other) for other in chosen):
                chosen.append(candidate)
                visit(position + 1, chosen)
                chosen.pop()

    visit(0, [])
    if stats["found"] == 0:
        raise PlannerError(_explain_impossible(courses, options))
    seen: list[tuple] = []
    for item in best:
        key = item.metrics.as_tuple(order)
        if key not in seen:
            seen.append(key)
        item.rank = seen.index(key) + 1
    return SearchResult(
        best=best,
        total=stats["found"],
        complete=not stats["capped"],
        explored=stats["explored"],
    )

